observation.query:
SELECT DISTINCT ?graph ?subject ?predicate ?object
WHERE {
  VALUES ?graph {
    <urn:graphragprov:unit:u_27bd8a3fe6fa14fc>
    <urn:graphragprov:unit:u_33dcc31f0cafc126>
    <urn:graphragprov:unit:u_ed4b4d73b120c1f2>
  }
  GRAPH ?graph {
    ?subject ?predicate ?object .
    FILTER(isIRI(?subject))
  }
}
ORDER BY ?graph ?subject ?predicate ?object
